<?php require 'config/database.php';require 'includes/auth.php';require_role('student');$q=$pdo->prepare("SELECT * FROM wallet_transactions WHERE user_id=? ORDER BY created_at DESC");$q->execute([current_user()['id']]);$rows=$q->fetchAll();$pageTitle='Transaction history';include 'includes/header.php';?>
<div class="page-heading"><span class="eyebrow">YOUR WALLET</span><h1>Transaction history</h1><p>A record of your earned and redeemed points.</p></div><section class="panel"><?php if(!$rows):?><div class="empty-state">No transactions to show yet.</div><?php else:foreach($rows as $t):?><div class="activity-row"><span class="activity-icon">♻</span><div><b><?=htmlspecialchars($t['description'])?></b><small><?=htmlspecialchars($t['created_at'])?></small></div><strong class="<?=$t['points']>=0?'positive':'negative'?>"><?=$t['points']>0?'+':''?><?=$t['points']?> pts</strong></div><?php endforeach;endif;?></section><?php include 'includes/footer.php';?>
